              "minLength": 1
            },
            "url": {
              "type": "string",
              "maxLength": 2048,
              "minLength": 1,
              "format": "safe-url"
            }
          }
        }
      }
    }
  },
  "providerKey": null,
  "cache": {
    "scope": "public",
    "ttlSeconds": 3600,
    "varyBy": [
      "tenant",
      "locale",
      "release"
    ]
